/**
 * @summary Upload Logo
 * @description Upload a custom logo for the admin UI.
 * Accepts image files (PNG, JPG, JPEG, SVG) and stores them for use in the UI.
 * @link /upload/logo
 */
export async function uploadLogoUploadLogoPost(
	{
		body,
		config,
	}: {
		body: UploadLogoUploadLogoPostBody;
		config?: Partial<FetcherConfig> & { client?: typeof defaultClient };
	} = {} as any,
) {
	const { client: request = defaultClient, ...requestConfig } = config ?? {};

	const formData = new FormData();
	if (body) {
		for (const [key, value] of Object.entries(body as Record<string, unknown>)) {
			for (const item of Array.isArray(value) ? value : [value]) {
				if (typeof item === "string" || item instanceof Blob) {
					formData.append(key, item);
				} else if (
					typeof item === "number" ||
					typeof item === "boolean" ||
					typeof item === "bigint"
				) {
					formData.append(key, String(item));
				} else if (item != null) {
					formData.append(key, JSON.stringify(item));
				}
			}
		}
	}
	const data = await request<
		UploadLogoUploadLogoPostResponse,
		ErrorWrapper<UploadLogoUploadLogoPostStatus422>,
		FormData,
		Record<string, string>,
		Record<string, string>,
		Record<string, string>
	>({
		method: "POST",
		url: `/upload/logo`,
		body: formData,
		...requestConfig,
		headers: { "Content-Type": "multipart/form-data", ...requestConfig.headers },
	});

	return data;
}

