/**
 * @summary Convert Prompt File To Json
 * @description Convert a .prompt file to JSON format.
 * This endpoint accepts a .prompt file upload and returns the equivalent JSON representation
 * that can be stored in a database or used programmatically.
 * Returns the JSON structure with 'content' and 'metadata' fields.
 * @link /utils/dotprompt_json_converter
 */
export async function convertPromptFileToJsonUtilsDotpromptJsonConverterPost(
	{
		body,
		config,
	}: {
		body: ConvertPromptFileToJsonUtilsDotpromptJsonConverterPostBody;
		config?: Partial<FetcherConfig> & { client?: typeof defaultClient };
	} = {} as any,
) {
	const { client: request = defaultClient, ...requestConfig } = config ?? {};

	const formData = new FormData();
	if (body) {
		for (const [key, value] of Object.entries(body as Record<string, unknown>)) {
			for (const item of Array.isArray(value) ? value : [value]) {
				if (typeof item === "string" || item instanceof Blob) {
					formData.append(key, item);
				} else if (
					typeof item === "number" ||
					typeof item === "boolean" ||
					typeof item === "bigint"
				) {
					formData.append(key, String(item));
				} else if (item != null) {
					formData.append(key, JSON.stringify(item));
				}
			}
		}
	}
	const data = await request<
		ConvertPromptFileToJsonUtilsDotpromptJsonConverterPostResponse,
		ErrorWrapper<ConvertPromptFileToJsonUtilsDotpromptJsonConverterPostStatus422>,
		FormData,
		Record<string, string>,
		Record<string, string>,
		Record<string, string>
	>({
		method: "POST",
		url: `/utils/dotprompt_json_converter`,
		body: formData,
		...requestConfig,
		headers: { "Content-Type": "multipart/form-data", ...requestConfig.headers },
	});

	return data;
}

